const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to evaluate ee.Objects as Promises
  const evaluate = (obj) => new Promise((resolve, reject) => obj.evaluate((res, err) => err ? reject(err) : resolve(res)));

  try {
    // 1. Geometry & Time Definitions
    const af = ee.FeatureCollection('FAO/GAUL/2015/level0').filter(ee.Filter.eq('ADM0_NAME', 'Afghanistan')).geometry();
    // Northern Afghanistan approx box; intersect with country boundary
    const northBox = ee.Geometry.Rectangle([60.0, 35.0, 74.5, 38.5], null, false);
    const region = af.intersection(northBox, ee.ErrorMargin(1000));

    const scale = 3000; // coarse to avoid timeouts
    const summerMonthsFilter = ee.Filter.calendarRange(6, 8, 'month');

    // 2. Data Acquisition & Builders
    function buildMOD13(start, end) {
      return ee.ImageCollection('MODIS/061/MOD13A2')
        .filterDate(start, end)
        .filterBounds(region)
        .filter(summerMonthsFilter)
        .map(function(img) {
          const ndvi = img.select('NDVI').multiply(0.0001); // scale factor
          const qa = img.select('SummaryQA'); // 0=Good,1=Marginal,2=Snow/Ice,3=Cloud
          const mask = qa.lte(1);
          return ndvi.updateMask(mask).rename('NDVI').copyProperties(img, img.propertyNames());
        });
    }

    function buildMOD09(start, end) {
      return ee.ImageCollection('MODIS/061/MOD09Q1')
        .filterDate(start, end)
        .filterBounds(region)
        .filter(summerMonthsFilter)
        .map(function(img) {
          // Cloud state bits 10-11: 00=clear
          const state = img.select('state_1km');
          const cloudState = state.bitwiseAnd(3 << 10).rightShift(10);
          const qc = img.select('sur_refl_qc_250m'); // 0 = good data
          const mask = cloudState.eq(0).and(qc.eq(0));
          const ndvi = img.normalizedDifference(['sur_refl_b02', 'sur_refl_b01']).rename('NDVI');
          return ndvi.updateMask(mask).copyProperties(img, img.propertyNames());
        });
    }

    async function pickCollection(start, end) {
      let col = buildMOD13(start, end);
      let size = await evaluate(col.size());
      if (size === 0) {
        col = buildMOD09(start, end);
        size = await evaluate(col.size());
        return { col, size, dataset: size === 0 ? 'None' : 'MOD09Q1' };
      }
      return { col, size, dataset: 'MOD13A2' };
    }

    function computeStats(col) {
      const totalPix = ee.Number(
        ee.Image(1).rename('one').reduceRegion({
          reducer: ee.Reducer.count(),
          geometry: region,
          scale: scale,
          maxPixels: 1e9,
          bestEffort: true
        }).get('one')
      );

      // Per-image spatial mean and valid pixel count
      const fc = ee.FeatureCollection(
        col.map(function(img) {
          const d = img.reduceRegion({
            reducer: ee.Reducer.mean().combine({ reducer2: ee.Reducer.count(), sharedInputs: true }),
            geometry: region,
            scale: scale,
            maxPixels: 1e9,
            bestEffort: true
          });
          const mean = ee.Number(d.get('NDVI_mean'));
          const count = ee.Number(d.get('NDVI_count'));
          return ee.Feature(null, { mean: mean, count: count });
        })
      );

      const fcValid = fc.filter(ee.Filter.gt('count', 0));
      const imgCount = col.size();
      const validImgCount = fcValid.size();
      const meanNDVI = ee.Number(fcValid.aggregate_mean('mean'));
      const avgValidPix = ee.Number(fcValid.aggregate_mean('count'));
      const covPct = avgValidPix.divide(totalPix).multiply(100);

      return ee.Dictionary({
        imgCount: imgCount,
        validImgCount: validImgCount,
        meanNDVI: meanNDVI,
        avgValidPix: avgValidPix,
        totalPix: totalPix,
        covPct: covPct
      });
    }

    // Periods
    const baseStart = '2000-06-01', baseEnd = '2013-08-31';
    const y2018Start = '2018-06-01', y2018End = '2018-08-31';

    // 3. Collections with fallback logic
    const basePick = await pickCollection(baseStart, baseEnd);
    const y2018Pick = await pickCollection(y2018Start, y2018End);

    if (basePick.size === 0 || y2018Pick.size === 0) {
      console.log(`Region pixels (3km): ${await evaluate(ee.Number(ee.Image(1).reduceRegion({reducer: ee.Reducer.count(), geometry: region, scale: scale, maxPixels: 1e9, bestEffort: true}).get('constant')).unbounded()) || 'NA'}`);
      console.log(`Baseline Images: ${basePick.size} | Dataset: ${basePick.dataset}`);
      console.log(`2018 Images: ${y2018Pick.size} | Dataset: ${y2018Pick.dataset}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }

    // 4. Processing and stats
    const baseStats = computeStats(basePick.col);
    const y2018Stats = computeStats(y2018Pick.col);

    const results = await evaluate(ee.Dictionary({
      totalPix: ee.Number(ee.Image(1).rename('one').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9,
        bestEffort: true
      }).get('one')),
      baseImgCount: baseStats.get('imgCount'),
      baseValidImgCount: baseStats.get('validImgCount'),
      baseMean: baseStats.get('meanNDVI'),
      baseAvgValid: baseStats.get('avgValidPix'),
      baseCovPct: baseStats.get('covPct'),
      y2018ImgCount: y2018Stats.get('imgCount'),
      y2018ValidImgCount: y2018Stats.get('validImgCount'),
      y2018Mean: y2018Stats.get('meanNDVI'),
      y2018AvgValid: y2018Stats.get('avgValidPix'),
      y2018CovPct: y2018Stats.get('covPct')
    }));

    // 5. Validation & Final Answer
    const tp = results.totalPix || 0;
    const bImg = results.baseImgCount || 0;
    const bVImg = results.baseValidImgCount || 0;
    const bMean = results.baseMean;
    const bAvg = results.baseAvgValid || 0;
    const bCov = results.baseCovPct;
    const yImg = results.y2018ImgCount || 0;
    const yVImg = results.y2018ValidImgCount || 0;
    const yMean = results.y2018Mean;
    const yAvg = results.y2018AvgValid || 0;
    const yCov = results.y2018CovPct;

    console.log(`Region pixels (3km): ${tp}`);
    console.log(`Baseline Dataset: ${basePick.dataset} | 2018 Dataset: ${y2018Pick.dataset}`);
    console.log(`Baseline JJA(2000-2013): Images: ${bImg} (valid imgs: ${bVImg}), Mean NDVI: ${bMean !== null ? bMean.toFixed(3) : 'null'}, Avg valid px: ${Math.round(bAvg)} (cov: ${bCov !== null ? bCov.toFixed(1) : 'null'}%)`);
    console.log(`2018 JJA: Images: ${yImg} (valid imgs: ${yVImg}), Mean NDVI: ${yMean !== null ? yMean.toFixed(3) : 'null'}, Avg valid px: ${Math.round(yAvg)} (cov: ${yCov !== null ? yCov.toFixed(1) : 'null'}%)`);

    // Handle C2 and C3
    if (bVImg === 0 || yVImg === 0 || bAvg === 0 || yAvg === 0) {
      console.log('No valid pixels after masking in one or both periods.');
      console.log('C2');
      return;
    }
    if (bMean === null || yMean === null || isNaN(bMean) || isNaN(yMean) || bMean < -0.2 || bMean > 1.0 || yMean < -0.2 || yMean > 1.0) {
      console.log('Calculation failure or invalid NDVI range.');
      console.log('C3');
      return;
    }

    const diff = yMean - bMean;
    console.log(`Diff (2018 - baseline): ${diff.toFixed(3)}`);

    // Decision with small tolerance
    if (diff < -0.010) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }

  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
